sys_ws_operation.operation_script:
(function process(/*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {

    try {

        // 🔥 PURE ARRAY BODY
        var employees = request.body.data;

        // Validate array
        if (!employees || !Array.isArray(employees)) {
            response.setStatus(400);
            response.setBody({
                error: "Request body must be an array anitha pandi"
            });
            return;
        }

        var result = [];
        var gL = employees.length;
		gs.info("Employee Length"+gL);

        for (var i = 0; i < employees.length; i++) {

            var emp = employees[i];

            if (!emp.u_empnumber) {
                result.push({
                    status: "failed",
                    reason: "u_empnumber missing",
                    record: emp
                });
                continue;
            }

            var gr = new GlideRecord('u_employee');
            gr.initialize();
            gr.setValue('u_empnumber', emp.u_empnumber);
            gr.setValue('u_firstname', emp.u_firstname);
            gr.setValue('u_lastname', emp.u_lastname);
            gr.setValue('u_age', emp.u_age);
            gr.setValue('u_createdby', emp.u_createdby);
            gr.setValue('u_salary', emp.u_salary);

            var sysId = gr.insert();

            result.push({
                status: sysId ? "success" : "failed",
                emp_number: emp.u_empnumber,
                sys_id: sysId || ""
            });
        }

        response.setStatus(201);
        response.setBody({
            message: "Employees processed",
            result: result
        });

    } catch (ex) {
        gs.error("Employee API error: " + ex);

        response.setStatus(500);
        response.setBody({
            error: "Internal Server Error",
            message: ex.toString()
        });
    }

})(request, response);
